// Actual ConfigHandler and selected actual daemon methods. No daemon constructor/main.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const [tsModule,sourceArg,group='valid',kind='ts',generatedArg]=process.argv.slice(2);
assert(tsModule && sourceArg, 'explicit existing TypeScript module and prepared source required');
const source=path.resolve(sourceArg),generated=generatedArg && path.resolve(generatedArg);
const ts=require(path.resolve(tsModule)),mode=path.basename(source);
const sha=s=>crypto.createHash('sha256').update(s).digest('hex'),plain=x=>JSON.parse(JSON.stringify(x));
const files=['classes/ConfigHandler','models/DefaultProfiles','models/TccProfile','models/TccFanTable','models/TccSettings','models/profiles/LegacyProfiles'];
const compile=text=>ts.transpileModule(text,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
const hashes={};
function moduleText(id) {
 const file=path.join(source,'src/common',id+'.ts');
 const text=fs.readFileSync(file,'utf8');hashes[file]=sha(text);return text;
}
const daemonPath=path.join(source,'src/service-app/classes/TuxedoControlCenterDaemon.ts');
const daemonText=fs.readFileSync(daemonPath,'utf8');hashes[daemonPath]=sha(daemonText);
const ast=ts.createSourceFile('daemon.ts',daemonText,ts.ScriptTarget.Latest,true);
const cls=ast.statements.find(n=>ts.isClassDeclaration(n)&&n.name.text==='TuxedoControlCenterDaemon');
const methods=['readOrCreateConfigurationFiles','loadConfigsAndProfiles','syncOutputPortsSetting'].map(n=>{const m=cls.members.find(m=>m.name?.getText(ast)===n);assert(m,n);return m.getText(ast)}).join('\n');
if(group==='emit') {
 assert(generated, 'explicit generated JS output required');
 for(const id of files) {const p=path.join(generated,'common',id+'.js');fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,compile(moduleText(id)));}
 const p=path.join(generated,'daemon-methods.js');fs.writeFileSync(p,compile('class ConfigHarness { '+methods+' }; export {ConfigHarness};'));
 fs.writeFileSync(path.join(generated,'source-hashes.json'),JSON.stringify(hashes,null,2)+'\n');console.log('emitted independent JS',mode);process.exit(0);
}
if(kind==='js') {
 assert(generated, 'explicit independent generated JS input required');
 const saved=JSON.parse(fs.readFileSync(path.join(generated,'source-hashes.json')));
 for(const [p,h] of Object.entries(saved))assert.equal(sha(fs.readFileSync(p)),h,'generated source stale');
}
let checks=0;
function check(fn) {fn();checks++;}
const settingsPath='/mock/tcc/settings', profilesPath='/mock/tcc/profiles';
function build(options={}) {
 const data=new Map(),writes=[],reads=[],logs=[];let readFault=options.readFault,writeFault=options.writeFault;
 const fakeFs={readFileSync(n){reads.push(n);if(n===settingsPath&&readFault)throw readFault;if(!data.has(n))throw Object.assign(new Error('absent '+n),{code:'ENOENT'});return Buffer.from(data.get(n));},writeFileSync(n,b){if(n===settingsPath&&writeFault)throw writeFault;writes.push({path:n,bytes:String(b)});data.set(n,Buffer.from(b));},existsSync(){return true;},mkdirSync(){throw new Error('unexpected mkdir');}};
 fakeFs.promises={readFile:async n=>fakeFs.readFileSync(n),writeFile:async(n,b)=>fakeFs.writeFileSync(n,b)};
 const cache=new Map(),context={console:{log:(...a)=>logs.push(a.map(String).join(' ')),error:(...a)=>logs.push(a.map(String).join(' '))}};
 function load(id){if(cache.has(id))return cache.get(id).exports;assert(files.includes(id),'unreviewed import '+id);const text=kind==='js'?fs.readFileSync(path.join(generated,'common',id+'.js'),'utf8'):compile(moduleText(id));const m={exports:{}};cache.set(id,m);const req=n=>{if(n==='node:fs')return fakeFs;if(n==='node:path')return path;if(n.startsWith('.'))return load(path.posix.normalize(path.posix.join(path.posix.dirname(id),n)));throw new Error('blocked require '+n)};vm.runInNewContext('(function(exports,require,module){'+text+'\n})',context,{timeout:1000})(m.exports,req,m);return m.exports;}
 const {ConfigHandler}=load('classes/ConfigHandler');const cfg=new ConfigHandler(settingsPath,profilesPath,'/mock/webcam','/mock/v4l2','/mock/fantables');
 const seed=plain(cfg.getDefaultSettings(undefined));seed.fanControlEnabled=false;
 const settings=Object.hasOwn(options,'settings')?options.settings:seed;
 if(!options.absent)data.set(settingsPath,Buffer.from(typeof settings==='string'?settings:JSON.stringify(settings)));
 data.set(profilesPath,Buffer.from(JSON.stringify(cfg.getDefaultCustomProfiles(undefined))));
 const model=load('models/DefaultProfiles'),states=load('models/TccSettings'),m={exports:{}};
 const code=kind==='js'?fs.readFileSync(path.join(generated,'daemon-methods.js'),'utf8'):compile('class ConfigHarness { '+methods+' }; export {ConfigHarness};');
 vm.runInNewContext('(function(exports){'+code+'\n})',{...context,defaultCustomProfile:model.defaultCustomProfile,ProfileStates:states.ProfileStates,TuxedoIOAPI:{getOutputPorts:()=>{if(options.portsFault)throw options.portsFault;return options.ports||[]}}},{timeout:1000})(m.exports);
 const d=new m.exports.ConfigHarness();Object.assign(d,{config:cfg,dbusData:{},logLine:s=>logs.push(s),identifyDevice:()=>undefined,deviceHasAquaris:()=>false,getIsUnsupportedConfigurableTGPDevice:()=>false,fillDeviceSpecificDefaults:x=>x,getCurrentProfile:()=>undefined,getDefaultProfile:()=>d.customProfiles?.[0]});
 return{cfg,d,writes,reads,data,logs,seed,settings,setReadFault:x=>readFault=x,setWriteFault:x=>writeFault=x};
}
const groups={
 async valid(){const h=build();const before=h.data.get(settingsPath).toString();check(()=>assert.equal(h.cfg.readSettings().fanControlEnabled,false));check(()=>assert.equal((h.d.loadConfigsAndProfiles(),h.d.settings.fanControlEnabled),false));check(()=>assert.equal(h.writes.length,0));check(()=>assert.equal(h.data.get(settingsPath).toString(),before));check(()=>assert.equal(JSON.parse(h.d.dbusData.settingsJSON).fanControlEnabled,false));check(()=>assert.equal((h.cfg.readSettings()).cpuSettingsEnabled,true));const a=await h.cfg.readSettingsAsync();check(()=>assert.equal(a.fanControlEnabled,false));},
 async stringfalse(){const h=build();const s=plain(h.seed);s.fanControlEnabled='false';h.data.set(settingsPath,Buffer.from(JSON.stringify(s)));check(()=>assert.throws(()=>h.cfg.readSettings(),e=>e.name==='TypeError'));await assert.rejects(h.cfg.readSettingsAsync(),e=>e.name==='TypeError');checks++;check(()=>assert.throws(()=>h.d.loadConfigsAndProfiles(),e=>e.name==='TypeError'));check(()=>assert.equal(h.writes.length,0));check(()=>assert.equal(h.d.settings,undefined));},
 async schema(){const bad=[null,[],false,17,'"false"',...['fahrenheit','cpuSettingsEnabled','fanControlEnabled','keyboardBacklightControlEnabled'].flatMap(k=>[{[k]:'false'},{[k]:0},{[k]:null}]),...['shutdownTime','chargingProfile','chargingPriority'].map(k=>({[k]:false})),{stateMap:null},{stateMap:[]},{stateMap:{power_ac:42}},{stateMap:{power_bat:false}},{ycbcr420Workaround:{}},{ycbcr420Workaround:[null]},{ycbcr420Workaround:[{'DP-1':'false'}]},{keyboardBacklightStates:{}},{keyboardBacklightStates:[null]},...['mode','brightness','red','green','blue'].map(k=>({keyboardBacklightStates:[{[k]:'2'}]}))];for(const settings of bad){const h=build({settings});const before=h.data.get(settingsPath).toString();check(()=>assert.throws(()=>h.cfg.readSettings(),e=>e.name==='TypeError'));await assert.rejects(h.cfg.readSettingsAsync(),e=>e.name==='TypeError');checks++;check(()=>assert.throws(()=>h.d.loadConfigsAndProfiles(),e=>e.name==='TypeError'));check(()=>assert.equal(h.writes.length,0));check(()=>assert.equal(h.data.get(settingsPath).toString(),before));check(()=>assert.equal(h.d.dbusData.settingsJSON,undefined));}const h=build({settings:'{"fanControlEnabled":true,"keyboardBacklightStates":[{"red":1e999}]}'});check(()=>assert.throws(()=>h.cfg.readSettings(),e=>e.name==='TypeError'));},
 async ioerrors(){for(const code of ['EACCES','EIO','ENOTDIR','EPERM']){const err=Object.assign(new Error(code),{code}),h=build({readFault:err});check(()=>assert.throws(()=>h.cfg.readSettings(),e=>e===err));await assert.rejects(h.cfg.readSettingsAsync(),e=>e===err);checks++;check(()=>assert.throws(()=>h.d.loadConfigsAndProfiles(),e=>e===err));check(()=>assert.equal(h.writes.length,0));check(()=>assert.equal(h.d.settings,undefined));}},
 async malformed(){const h=build({settings:'{broken'});check(()=>assert.throws(()=>h.d.loadConfigsAndProfiles(),e=>e.name==='SyntaxError'));check(()=>assert.equal(h.data.get(settingsPath).toString(),'{broken'));check(()=>assert.equal(h.writes.length,0));check(()=>assert.equal(h.d.dbusData.settingsJSON,undefined));check(()=>assert.equal(h.reads.filter(n=>n===profilesPath).length,0));},
 async reload(){const h=build();h.d.loadConfigsAndProfiles();const old=h.d.settings;h.data.set(settingsPath,Buffer.from('{broken-reload'));check(()=>assert.throws(()=>h.d.loadConfigsAndProfiles(),e=>e.name==='SyntaxError'));check(()=>assert.equal(h.d.settings,old));check(()=>assert.equal(h.d.settings.fanControlEnabled,false));check(()=>assert.equal(h.writes.length,0));check(()=>assert.equal(h.data.get(settingsPath).toString(),'{broken-reload'));},
 async missingfile(){const h=build({absent:true});h.d.loadConfigsAndProfiles();check(()=>assert.equal(h.d.settings.fanControlEnabled,true));check(()=>assert.equal(h.writes.filter(w=>w.path===settingsPath).length,1));check(()=>assert.equal(JSON.parse(h.data.get(settingsPath)).fanControlEnabled,true));check(()=>assert.equal(h.d.customProfiles.length>0,true));},
 async missingfields(){for(const field of ['stateMap','cpuSettingsEnabled','fanControlEnabled','keyboardBacklightControlEnabled','ycbcr420Workaround','chargingProfile','chargingPriority','keyboardBacklightStates']){const h=build(),s=plain(h.seed);delete s[field];h.data.set(settingsPath,Buffer.from(JSON.stringify(s)));check(()=>assert.doesNotThrow(()=>h.cfg.readSettings()));h.d.loadConfigsAndProfiles();check(()=>assert.equal(h.writes.filter(w=>w.path===settingsPath).length,1));check(()=>assert.deepEqual(plain(h.d.settings[field]),plain(h.cfg.getDefaultSettings(undefined)[field])));}const h=build();h.data.set(settingsPath,Buffer.from('{"fanControlEnabled":false}'));h.d.loadConfigsAndProfiles();check(()=>assert.equal(h.d.settings.fanControlEnabled,false));check(()=>assert.equal(h.writes.filter(w=>w.path===settingsPath).length,1));},
 async writeerrors(){for(const options of [{absent:true},{settings:{fanControlEnabled:false}}]){const err=Object.assign(new Error('write denied'),{code:'EACCES'}),h=build({...options,writeFault:err});const before=h.data.get(settingsPath)?.toString();check(()=>assert.throws(()=>h.d.loadConfigsAndProfiles(),e=>e===err));check(()=>assert.equal(h.writes.length,0));check(()=>assert.equal(h.data.get(settingsPath)?.toString(),before));check(()=>assert.equal(h.d.dbusData.settingsJSON,undefined));check(()=>assert.equal(h.reads.filter(n=>n===profilesPath).length,0));}},
 async ports(){const h=build({ports:[['DP-1','HDMI-1']]});h.d.loadConfigsAndProfiles();check(()=>assert.deepEqual(plain(h.d.settings.ycbcr420Workaround),[{'DP-1':false,'HDMI-1':false}]));check(()=>assert.equal(h.writes.filter(w=>w.path===settingsPath).length,1));h.d.loadConfigsAndProfiles();check(()=>assert.equal(h.writes.filter(w=>w.path===settingsPath).length,1));},
 async compatibility(){const h=build(),s=plain(h.seed);s.extension={future:true};s.shutdownTime='';s.chargingProfile=null;s.chargingPriority='';s.keyboardBacklightStates=[{mode:0,brightness:25.5}];h.data.set(settingsPath,Buffer.from(JSON.stringify(s)));h.d.loadConfigsAndProfiles();check(()=>assert.deepEqual(plain(h.d.settings),s));check(()=>assert.equal(h.writes.length,0));const nested=build(),ns=plain(nested.seed);delete ns.stateMap.power_bat;nested.data.set(settingsPath,Buffer.from(JSON.stringify(ns)));nested.d.loadConfigsAndProfiles();check(()=>assert.equal(typeof nested.d.settings.stateMap.power_bat,'string'));check(()=>assert.equal(nested.writes.filter(w=>w.path===settingsPath).length,1));},
 async rollback(){for(const failure of ['write','ports','missingfile']){const h=build();h.d.loadConfigsAndProfiles();const old=h.d.settings,oldBytes=JSON.stringify(old);let next=plain(h.seed);next.fanControlEnabled=true;delete next.cpuSettingsEnabled;h.data.set(settingsPath,Buffer.from(JSON.stringify(next)));const err=Object.assign(new Error(failure),{code:'EIO'});if(failure==='missingfile')h.data.delete(settingsPath);if(failure==='ports'){const x=build({portsFault:err});x.d.settings=old;check(()=>assert.throws(()=>x.d.loadConfigsAndProfiles(),e=>e===err));check(()=>assert.equal(x.d.settings,old));check(()=>assert.equal(JSON.stringify(x.d.settings),oldBytes));check(()=>assert.equal(x.writes.length,0));}else{h.setWriteFault(err);const before=h.data.get(settingsPath)?.toString();check(()=>assert.throws(()=>h.d.loadConfigsAndProfiles(),e=>e===err));check(()=>assert.equal(h.d.settings,old));check(()=>assert.equal(JSON.stringify(h.d.settings),oldBytes));check(()=>assert.equal(h.data.get(settingsPath)?.toString(),before));check(()=>assert.equal(h.writes.length,0));}}const h=build({absent:true,writeFault:Object.assign(new Error('denied'),{code:'EIO'})});check(()=>assert.throws(()=>h.d.loadConfigsAndProfiles()));check(()=>assert.equal(h.d.settings,undefined));const success=build();success.d.loadConfigsAndProfiles();const old=success.d.settings,next=plain(success.seed);next.fanControlEnabled=true;delete next.cpuSettingsEnabled;success.data.set(settingsPath,Buffer.from(JSON.stringify(next)));success.d.loadConfigsAndProfiles();check(()=>assert.notEqual(success.d.settings,old));check(()=>assert.equal(success.d.settings.fanControlEnabled,true));check(()=>assert.equal(success.writes.filter(w=>w.path===settingsPath).length,1));},
 async profiles(){const h=build();h.data.delete(profilesPath);h.d.readOrCreateConfigurationFiles(undefined);check(()=>assert.equal(h.writes.filter(w=>w.path===profilesPath).length,1));check(()=>assert.equal(h.writes.filter(w=>w.path===settingsPath).length,0));check(()=>assert.equal(h.d.settings.fanControlEnabled,false));},
 async mainorder(){const m=cls.members.find(m=>m.name?.getText(ast)==='main').getText(ast);const load=m.indexOf('this.loadConfigsAndProfiles()'),fan=m.indexOf('new FanControlWorker'),start=m.indexOf('this.startWorkers()');check(()=>assert(load>=0&&fan>load&&start>fan));check(()=>assert(!m.slice(load,fan).includes('.catch(')));}
};
(async()=>{assert(groups[group],'unknown group '+group);await groups[group]();console.log(JSON.stringify({mode,kind,group,checks,pass:true,source_hashes:hashes,scope:'actual ConfigHandler entire class + actual daemon 3methods; fs memory only, native output-port listing mocked, device fill identity, no daemon constructor/main/workers/hardware'}));})().catch(e=>{console.error(e);process.exitCode=1;});
